/**
 * In-memory gate for human-in-the-loop parks. The session engine parks
 * inside a server-tool `execute` by awaiting {@link ApprovalGate.wait};
 * HTTP (or the playground) unblocks via {@link ApprovalGate.resolve}.
 *
 * Used for `needsApproval` and MCP on-demand auth. Pending rows are also
 * mirrored onto {@link SessionRecord} for durability of the *list* across
 * reloads. After a process restart the in-flight SDK tool callback is gone,
 * so resolve returns false and the host treats the park as interrupted.
 */
function approvalKey(sessionId, callId) {
    return `${sessionId}\0${callId}`;
}
export class ApprovalGate {
    constructor() {
        this.waiters = new Map();
    }
    wait(sessionId, meta) {
        const key = approvalKey(sessionId, meta.callId);
        const existing = this.waiters.get(key);
        if (existing !== undefined) {
            throw new Error(`Approval already pending for session ${sessionId} call ${meta.callId}`);
        }
        return new Promise((resolveDecision) => {
            this.waiters.set(key, {
                meta,
                resolve: resolveDecision,
            });
        });
    }
    /**
     * Unblock a waiter. Returns false when there is no live waiter (e.g. the
     * host restarted while the tool call was parked).
     */
    resolve(sessionId, callId, decision, resolvedBy, approver) {
        const key = approvalKey(sessionId, callId);
        const waiter = this.waiters.get(key);
        if (waiter === undefined) {
            return false;
        }
        this.waiters.delete(key);
        const by = resolvedBy === undefined || resolvedBy === "" ? undefined : resolvedBy;
        waiter.resolve({
            decision,
            by,
            approver,
        });
        return true;
    }
    has(sessionId, callId) {
        return this.waiters.has(approvalKey(sessionId, callId));
    }
    list(sessionId) {
        const prefix = `${sessionId}\0`;
        const out = [];
        for (const [key, waiter] of this.waiters) {
            if (key.startsWith(prefix)) {
                out.push(waiter.meta);
            }
        }
        return out;
    }
    /** Drop waiters for a session (e.g. turn already failed). */
    cancelSession(sessionId, decision = "deny") {
        const prefix = `${sessionId}\0`;
        for (const [key, waiter] of [...this.waiters.entries()]) {
            if (!key.startsWith(prefix)) {
                continue;
            }
            this.waiters.delete(key);
            waiter.resolve({ decision });
        }
    }
    /** Unblock every live waiter (e.g. engine shutdown). */
    cancelAll(decision = "deny") {
        for (const waiter of this.waiters.values()) {
            waiter.resolve({ decision });
        }
        this.waiters.clear();
    }
}
